    "/api/v1/products/bulk/excel": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        get?: never;
        put?: never;
        /**
         * Bulk create products from Excel file
         * @description Parses a filled-in .xlsx workbook, validates all rows, and queues the products for async creation via the same BullMQ pipeline as POST /bulk.
         *
         *     **Request:** multipart/form-data with a single field named `file` containing the .xlsx workbook.
         *
         *     **File requirements:**
         *     - Format: .xlsx only (not .xls, not .csv)
         *     - Max size: 5 MB
         *     - Must contain sheets named "Products" and "Variants" (exact names)
         *     - Max 100 products, max 50 variants per product, max 700 total data rows
         *
         *     **Rate limit:** Shares the bulk-create rate limit with POST /bulk — 5 uploads per hour per staff member.
         */
        post: {
            parameters: {
                query?: never;
                header?: never;
                path?: never;
                cookie?: never;
            };
            requestBody: {
                content: {
                    "multipart/form-data": {
                        /**
                         * Format: binary
                         * @description The .xlsx workbook file. Field name must be "file". Max 5 MB.
                         */
                        file: string;
                    };
                };
            };
            responses: {
                /** @description File parsed successfully — products queued for creation. Poll /bulk/:batchId for status. */
                202: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": {
                            success: boolean;
                            data: {
                                /**
                                 * @description Use this to poll GET /bulk/:batchId
                                 * @example BATCH-ABC1234567
                                 */
                                batchId: string;
                                /** @description BullMQ job ID */
                                jobId: string;
                                /**
                                 * @description From the first row of the Products sheet
                                 * @example upload-batch-001
                                 */
                                idempotencyKey: string;
                                /**
                                 * @description Number of products queued
                                 * @example 12
                                 */
                                productCount: number;
                                message: string;
                            };
                        };
                    };
                };
                /** @description No file uploaded or invalid file type */
                400: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content?: never;
                };
                /** @description Insufficient permissions — requires products:bulk:write */
                403: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content?: never;
                };
                /** @description Validation errors found — fix the listed errors and re-upload */
                422: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": {
                            /** @example false */
                            success: boolean;
                            /** @example The uploaded file contains errors. Fix them and re-upload. */
                            message: string;
                            rowErrors: {
                                /**
                                 * @description Sheet name: "Products" or "Variants"
                                 * @example Products
                                 */
                                sheet: string;
                                /**
                                 * @description 1-based Excel row number. 0 = file-level error.
                                 * @example 3
                                 */
                                row: number;
                                /**
                                 * @description Column header name (absent for file-level errors)
                                 * @example categoryId
                                 */
                                column?: string;
                                /** @example categoryId is not a valid UUID. Copy it from the categories list. */
                                message: string;
                            }[];
                        };
                    };
                };
                /** @description Bulk create rate limit exceeded — 5 per hour per staff member */
                429: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content?: never;
                };
                /** @description Too many concurrent uploads in progress — try again in a moment */
                503: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content?: never;
                };
            };
        };
        delete?: never;
        options?: never;
        head?: never;
        patch?: never;
        trace?: never;
    };
